head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gIsurCd;
scwin.gAcptNo;
scwin.gViewerStat = "P"; // 처리시 뷰어=P,  조회시 뷰어=R

scwin.gParamObj = new Array(4);
scwin.vScrenID = 'ULDSTF30010.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    $c.stf.setObjectValue(edt_SDATE, $c.ut.cGetToday2());
    $c.stf.setObjectValue(edt_EDATE, $c.ut.cGetToday2());
    $c.stf.setObjectValue(cmb_DEP_CD, js_dep_cd);
    $c.stf.setObjectValue(cmb_EMP_NO, js_emp_no);

    //유가/코스닥 주식시장운영팀일때 부서코드 전체,담당자 전체로 초기화한다.
    if (scwin.gDepCd == '2220' || scwin.gDepCd == '3220') {
        $c.stf.setObjectValue(cmb_DEP_CD, "");
        $c.stf.setObjectValue(cmb_EMP_NO, "");
    }
};
scwin.fn_SetCode = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + js_dep_cd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + js_dep_cd;
    dts_DEP_CD.Reset();
};
scwin.fn_HideDebugCtrls = function() {
    //showObj(panel_hidden_values, false);

};
scwin.fn_CheckCond = function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_SDATE).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_SDATE.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_EDATE).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_EDATE.focus();
        return;
    }
    scwin.fn_SearchMain();
};
scwin.fn_SearchMain = function() {
    var edt_FromDate_year = $c.stf.getObjectValue(edt_SDATE).substr(0, 4);
    var edt_FromDate_month = $c.stf.getObjectValue(edt_SDATE).substr(4, 2) - 1;
    var edt_FromDate_day = $c.stf.getObjectValue(edt_SDATE).substr(6, 2);
    var edt_FromDate_Date = new Date(edt_FromDate_year, edt_FromDate_month, edt_FromDate_day);
    var edt_ToDate_year = $c.stf.getObjectValue(edt_EDATE).substr(0, 4);
    var edt_ToDate_month = $c.stf.getObjectValue(edt_EDATE).substr(4, 2) - 1;
    var edt_ToDate_day = $c.stf.getObjectValue(edt_EDATE).substr(6, 2);
    var edt_ToDate_Date = new Date(edt_ToDate_year, edt_ToDate_month, edt_ToDate_day);


    // 1년 이상의 기간은 검색 할 수 없다
    var date_result = (Date.parse(edt_ToDate_Date) - Date.parse(edt_FromDate_Date)) / (1000 * 60 * 60 * 24);
    if (date_result > 365) {
        $c.win.alert("검색기간은 1년을 초과할 수 없습니다.");
        return;
    }

    // 코스닥이랑 같이 사용하는 기능으로 함수명 바꾸면 안됨.
    //var COM_NM = getObjectValue(txb_COM_NM);
    var ISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    var DEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);
    var EMP_NO = $c.stf.getObjectValue(cmb_EMP_NO);
    var SDATE = $c.stf.getObjectValue(edt_SDATE);
    var EDATE = $c.stf.getObjectValue(edt_EDATE);
    var STATUS = $c.stf.getObjectValue(cmb_STATUS);
    //var FORM_KOR_NM = getObjectValue(txb_FORM_KOR_NM);
    var FORM_CD = $c.stf.getObjectValue(txb_FORM_CD);
    var url = "/DisclosureSchedule.do?method=listScheduleEx";
    url += "&MKT_ID=" + js_market;
    url += "&TEAM_ID=" + js_team;
    url += "&ISUR_CD=" + ISUR_CD;
    url += "&DEP_CD=" + DEP_CD;
    url += "&EMP_NO=" + EMP_NO;
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;
    url += "&STATUS=" + STATUS;
    url += "&FORM_CD=" + FORM_CD;
    url += "&TEAM_ID=" + js_team;
    url += "&DISCLS_SCHDL_GRD_CD=" + $c.stf.getObjectValue(cmb_DISCLS_SCHDL_GRD_CD);
    url += "&MNGR_CLS_YN=" + $c.stf.getObjectValue(cmb_MNGR_CLS_YN);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;


    //alert(encodeURI(url));
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.openNew = async function() {
    scwin.fn_setParam("C", "", "", ""); //수정모드에서 잔상이 남아 신규일때는 강제로 값 세팅함.

    var url = "/dsclmgt/ULDSTF30001.gfm";
    var winTitle = "신규";
    await $c.frame.CreateFrame("ULDSTF30001", url, winTitle, 10, 10, 10, 20, "window", 0, 0, true);
    //frame.CreateDialogFrame("child01", "/dsclmgt/ULDSTF30001.gfm", "신규", 10, 10, 10, 20, "window");

};
scwin.fn_readSchedule = async function(GridID, row, colid) {
    if (row < 1) return;
    var CMD = "R";
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    var DISCLS_SCHDL_ADM_DD = objDataID.getCellData(row, "DISCLS_SCHDL_ADM_DD");
    var BYDD_SEQ = objDataID.getCellData(row, "BYDD_SEQ");
    var USR_ID = objDataID.getCellData(row, "INTEG_USR_ID");
    if (colid == "CD_NM") {
        if (scwin.fn_setParam(CMD, DISCLS_SCHDL_ADM_DD, BYDD_SEQ, USR_ID)) // formal arguments

        {
            var url = "/dsclmgt/ULDSTF30001.gfm";
            var winTitle = "일정조회";
            await $c.frame.CreateFrame("ULDSTF30001", url, winTitle, 10, 10, 10, 20, "window", 0, 0, true);
            //frame.CreateDialogFrame("child01", "/dsclmgt/ULDSTF30001.gfm", "일정조회", 10, 10, 10, 20, "window");

        }
    } else if (colid == "FORM_KOR_NM") {
        var AcptNo = objDataID.getCellData(row, "ACPT_NO");
        $c.stf.fn_OpenDisclViewer(AcptNo, "R");
    }
};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.btn_Search_onclick = function() {
    scwin.fn_CheckCond();
    //	fn_SearchMain();// 코스닥이랑 같이 사용하는 기능으로 함수명 바꾸면 안됨.

};
scwin.btn_ISUR_CD_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    dts_EMP_NO.sort("DEP_CD", 0);
    //dts_EMP_NO.sort(); // W-Craft 주석처리 
    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.btn_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE);
};
scwin.btn_RPT_onclick = async function() {
    await $c.frame.CreateDialogFrame("DLG_ISUR_CD_", "/dsclmgt/ULDSTF30003.gfm", "보고서 선택", 10, 10, 350, 570, "window");
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    var vVal = $c.stf.getObjectValue(cmb_DEP_CD);
    if (vVal == "") {
        // 전체일 경우
        return true;
    } else {
        var vVal2 = dts_EMP_NO.getCellData(row, "dep_cd"); // 전체.
        if (vVal2 == "") return true; // 전체.
        return (vVal == vVal2) ? true : false;
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "일정검색", "", "2");
};
scwin.btn_New_onclick = function() {
    scwin.openNew();
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (colid == "COM_ABBRV") {
        scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD");
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "FORM_KOR_NM") {
        scwin.fn_readSchedule(grd_Grid, row, colid);
    } else if (colid == "CD_NM") {
        scwin.fn_readSchedule(grd_Grid, row, colid);
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.top = "33px";
    Grd_com_isur.style.left = "85px";
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.btn_schedule_onclick = async function() {
    await $c.frame.CreateDialogFrame("gform", "/dsclmgt/ULDSTF30006.gfm", "공시일정추출현황", 300, 100, 1300, 750, "window");
};
scwin.gform_onload = function() {
    //fn_HideDebugCtrls();
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    scwin.fn_Init();
};
